    H, W = len(grid), len(grid[0])
    output = [[0]*W for _ in range(H)]

    for i in range(H):
        for j in range(W):
            if grid[i][j] != 9:
                output[i][j] = grid[i][j]
                continue

    for i in range(H):
        for j in range(W):
            if grid[i][j] == 9:
                # Check if this 9 has any vertical 9-neighbor
                has_vertical_neighbor = False
                if i > 0 and grid[i-1][j] == 9:
                    has_vertical_neighbor = True
                if i < H-1 and grid[i+1][j] == 9:
                    has_vertical_neighbor = True

                # For all-9s rows, just convert everything to 2
